INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_MODERN_PAGANISM','Modern Pagan & Esoteric Revival',1900,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_STRMISKA_MODERN_PAGANISM','secondary scholarship','Michael F. Strmiska (ed.), Modern Paganism in World Cultures: Comparative Perspectives (ABC-CLIO, 2005)','Modern Heathenry, Druidry, Goddess movement and reconstructionist Paganism worldwide'),
 ('SRC_ALBANESE_REPUBLIC_MIND','secondary scholarship','Catherine L. Albanese, A Republic of Mind and Spirit: A Cultural History of American Metaphysical Religion (Yale Univ. Press, 2007)','American metaphysical religion, New Thought, and the esoteric/Martinist lineage')
INSERT INTO _e VALUES
 ('ENT_NPG_HEATHENRY','Heathenry (Asatru)','movement','movement','Modern Paganism','modern revival of Norse/Germanic religion','B','Hub node for the modern Heathen / Asatru movement; an organized, legally-recognized revival religion (e.g. Iceland''s Asatruarfelagid, 1972) actively practicing blot and sumbel devotion to the Norse gods.'),
 ('ENT_NPG_NINE_NOBLE_VIRTUES','The Nine Noble Virtues','concept','concept','Modern Paganism','Heathen ethical code','C','An ethical egregore of modern Heathenry (formulated 1970s, Odinic Rite/Asatru Free Assembly) drawn from the Havamal and sagas; sincerely held as a moral framework, though its modern origin is acknowledged in the community.'),
 ('ENT_NPG_FOLK_UNIVERSALIST','Folkish–Universalist Distinction','concept','concept','Modern Paganism','Heathen identity debate','C','The defining internal distinction within practiced Heathenry over whether the faith is heritage-bound (folkish) or open to all (universalist); modeled neutrally as a belief-structure of the movement.'),
 ('ENT_NPG_DRUIDRY','Modern Druidry (OBOD/ADF)','movement','movement','Modern Paganism','modern revival of Celtic religion','B','Hub node for the practiced modern Druid movement (Order of Bards Ovates & Druids; Ar nDraiocht Fein), reconstructing Celtic devotion and seasonal ritual to the Celtic gods.'),
 ('ENT_NPG_GREAT_GODDESS','The Great Goddess (Goddess Movement)','deity','deity','Modern Paganism','the single immanent feminine divine','B','The one Great Goddess venerated in the Goddess movement and Dianic Wicca, of whom all named goddesses are held to be aspects; an actively-worshipped devotional figure.'),
 ('ENT_NPG_MARTINISM','Martinism','movement','movement','Modern Paganism','Christian-theurgic esoteric current','C','A practiced esoteric initiatory current descending from Martinez de Pasqually and Louis-Claude de Saint-Martin, surviving in modern Martinist orders.'),
 ('ENT_NPG_ELUS_COHENS','Order of Elus Cohens','order','order','Modern Paganism','theurgic Masonic order','C','Martinez de Pasqually''s Ordre des Chevaliers Macons Elus Coens de l''Univers, the theurgic order whose operative magic aimed at the Reintegration; revived and practiced in modern Martinism.'),
 ('ENT_NPG_REINTEGRATION','The Reintegration','concept','concept','Modern Paganism','Martinist soteriology','C','The central Martinist doctrine of the soul''s reintegration into divine unity after the Fall; a sincerely-held esoteric belief and the goal of Elus Cohen theurgy.'),
 ('ENT_NPG_REPAIRER','The Repairer (Le Reparateur)','concept','concept','Modern Paganism','Martinist redeemer-figure','C','The redemptive agent (the Christ/Repairer) who in Martinist theology effects the Reintegration of fallen humanity; modeled neutrally as a belief held within the tradition.'),
 ('ENT_NPG_DIVINE_MIND','Infinite Intelligence / Divine Mind','concept','concept','Modern Paganism','New Thought immanent divine','B','The impersonal immanent God-principle of practiced New Thought (Unity, Religious Science, etc.); ENT_VF_THE_UNIVERSE is its popular vernacular descendant.');
