INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_NPG_NINE_NOBLE_VIRTUES','associated_with','ENT_NPG_HEATHENRY','high','The Nine Noble Virtues function as the ethical code of the modern Heathen movement.'),
 ('ENT_NPG_FOLK_UNIVERSALIST','associated_with','ENT_NPG_HEATHENRY','high','The folkish-universalist distinction is the defining internal debate within Heathenry.'),
 ('ENT_NPG_HEATHENRY','reception_of','ENT_NOR_ODIN','high','Modern Heathens venerate Odin as a chief god of the reconstructed Norse pantheon.'),
 ('ENT_NPG_HEATHENRY','reception_of','ENT_NOR_THOR','high','Thor (Mjolnir cult) is among the most actively worshipped gods in modern Heathenry.'),
 ('ENT_NPG_HEATHENRY','reception_of','ENT_NOR_FREYJA','high','Freyja is widely venerated in modern Heathenry, especially in seidr practice.'),
 ('ENT_NPG_HEATHENRY','reception_of','ENT_NOR_FREYR','high','Freyr is honoured as a Vanir fertility god in modern Heathen blot.'),
 ('ENT_NPG_HEATHENRY','reception_of','ENT_NOR_FRIGG','medium','Frigg is received as a goddess of the household and hearth in modern Heathenry.'),
 ('ENT_NPG_HEATHENRY','reception_of','ENT_NOR_TYR','medium','Tyr is venerated as a god of justice and oaths in modern Heathenry.'),
 ('ENT_NPG_HEATHENRY','reception_of','ENT_NOR_BALDR','medium','Baldr is honoured within the reconstructed pantheon of modern Heathenry.'),
 ('ENT_NPG_HEATHENRY','reception_of','ENT_NOR_HEIMDALL','medium','Heimdall is received as a guardian god in modern Heathen devotion.'),
 ('ENT_NPG_HEATHENRY','reception_of','ENT_NOR_NJORD','medium','Njord is venerated as a Vanir sea god in modern Heathenry.'),
 ('ENT_NPG_HEATHENRY','reception_of','ENT_NOR_SKADI','medium','Skadi is honoured in modern Heathen practice as a goddess of winter and the hunt.'),
 ('ENT_NPG_HEATHENRY','reception_of','ENT_NOR_HEL','medium','Hel is received as a goddess of the dead by some modern Heathens.'),
 ('ENT_NPG_HEATHENRY','reception_of','ENT_NOR_LOKI','medium','Loki is venerated by a portion of modern Heathens, though contested within the community.'),
 ('ENT_NPG_DRUIDRY','reception_of','ENT_CEL_CERNUNNOS','high','Cernunnos is a central horned god honoured in modern Druidry and Celtic revival Paganism.'),
 ('ENT_NPG_DRUIDRY','reception_of','ENT_CEL_BRIGID','high','Brigid is among the most widely venerated deities in modern Druidry.'),
 ('ENT_NPG_DRUIDRY','reception_of','ENT_CEL_LUGH','high','Lugh is honoured in modern Druidry, especially at Lughnasadh.'),
 ('ENT_NPG_DRUIDRY','reception_of','ENT_CEL_DAGDA','medium','The Dagda is received as a father-god in modern Druidic devotion.'),
 ('ENT_NPG_DRUIDRY','reception_of','ENT_CEL_DANU','medium','Danu is venerated as a mother goddess in modern Druidry.'),
 ('ENT_NPG_DRUIDRY','reception_of','ENT_CEL_MANANNAN','medium','Manannan mac Lir is honoured as a sea god in modern Druidry.'),
 ('ENT_NPG_DRUIDRY','reception_of','ENT_CEL_EPONA','medium','Epona is received as a horse goddess in modern Druidic and Celtic-revival practice.'),
 ('ENT_NPG_DRUIDRY','reception_of','ENT_CEL_TARANIS','low','Taranis is venerated as a thunder god by some modern Druids reconstructing Gaulish religion.'),
 ('ENT_NPG_DRUIDRY','reception_of','ENT_CEL_BELENUS','low','Belenus is honoured as a sun/fire god in some modern Druidic reconstructions.'),
 ('ENT_NPG_GREAT_GODDESS','embodied_by','ENT_CEL_BRIGID','medium','In the Goddess movement, named goddesses such as Brigid are received as aspects/embodiments of the one Great Goddess.'),
 ('ENT_NPG_GREAT_GODDESS','embodied_by','ENT_NOR_FREYJA','low','The Goddess movement absorbs goddesses such as Freyja as faces of the single Great Goddess.'),
 ('ENT_NPG_ELUS_COHENS','member_of','ENT_NPG_MARTINISM','high','The Elus Cohens are the foundational theurgic order of the Martinist current.'),
 ('ENT_NPG_REINTEGRATION','associated_with','ENT_NPG_MARTINISM','high','The Reintegration is the central soteriological doctrine of Martinism and the Elus Cohens.'),
 ('ENT_NPG_REPAIRER','associated_with','ENT_NPG_REINTEGRATION','high','The Repairer is the redeemer-agent who effects the Reintegration in Martinist theology.'),
 ('ENT_NPG_ELUS_COHENS','associated_with','ENT_NPG_REINTEGRATION','medium','The theurgic operations of the Elus Cohens were directed toward attaining the Reintegration.'),
 ('ENT_VF_THE_UNIVERSE','reception_of','ENT_NPG_DIVINE_MIND','medium','The popular ''the Universe'' of contemporary vernacular spirituality is the direct descendant of New Thought''s Infinite Intelligence / Divine Mind.'),
 ('ENT_NPG_DIVINE_MIND','aligned_with','ENT_HER_WORLD_SOUL','low','New Thought''s immanent Divine Mind functionally parallels the Hermetic/Platonic World Soul as an all-pervading divine principle.'),
 ('ENT_NPG_REPAIRER','aligned_with','ENT_THE_SAINT_GERMAIN','low','Within the esoteric milieu the Martinist Repairer and Theosophical ascended masters share the role of redemptive spiritual mediators; noted as a loose functional alignment, not identity.');
